notes['233'] = {number:233,type:'LÉXICO Y DRAMATURGIA',heading:'Dos establos, ninguna protección',text:'Neutrubi y stabile stabulum prolongan la imagen del asno y el buey: Euclión teme quedar excluido tanto de su propio grupo como del de su vecino rico. Divorti es genitivo singular de divortium con grafía sincopada. Cotejo: Plauto, Aulularia 231–235, Friedrich Leo, Plauti Comoediae I (1895), texto reproducido en The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['235'] = {number:235,type:'MORFOLOGÍA',heading:'Periclum y fuat',text:'Periclum es variante sincopada de periculum; fuat (v. 233) es subjuntivo presente arcaico de sum, equivalente funcional de sit. El léxico ganadero sostiene la metáfora de la desigualdad económica. Fuente textual: Friedrich Leo (1895), Aulularia 233–235; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};

notes['223'] = {number:223,type:'MORFOLOGÍA',heading:'Derisum venio',text:'Derisum es supino en -um de derideo: expresa finalidad después del verbo de movimiento venio. No es un participio perfecto. Cotejo: Plauto, Aulularia 223, Friedrich Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['224'] = {number:224,type:'LÉXICO',heading:'Gnatam',text:'Gnatam es acusativo de gnata, variante antigua de nata («hija»), relacionada con el verbo nascor. La grafía forma parte del registro plautino; un paradigma clásico puede presentar nata. Texto: Friedrich Leo (1895), Aulularia 224, https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul.'};

// No permitir palabras sin glosa en los fragmentos ya publicados.
if (typeof aululariaGlosses === 'undefined') throw new Error('No se cargó glosses.js');
const missingGlosses = [...new Set(verses.flatMap(entry => entry.words
  .filter(word => !word[3] && !Object.hasOwn(aululariaGlosses, word[1]))
  .map(word => word[1])))];
if (missingGlosses.length) {
  throw new Error('Faltan glosas españolas para: ' + missingGlosses.join(', '));
}

