notes['256'] = {number:256,type:'LENGUAJE JURÍDICO',heading:'La fórmula de la promesa',text:'La alternancia despondes / sponden / spondeo dramatiza el consentimiento verbal del matrimonio; la forma sponden incorpora la interrogativa enclítica -ne. Cotejo: Plauto, Aulularia 255–256, texto latino en https://www.thelatinlibrary.com/plautus/aulularia.shtml (consultado 12-XI-2026).'};
notes['259'] = {number:259,type:'LENGUA Y RETÓRICA',heading:'La desconfianza convertida en juego verbal',text:'perplexarier conserva la terminación arcaica -ier de infinitivo; el juego pactum non pactum / non pactum pactum invierte las fórmulas del acuerdo para expresar el temor de Euclión a que se alteren sus condiciones. Plauto, Aulularia 259–260, https://www.thelatinlibrary.com/plautus/aulularia.shtml. La clasificación exacta de perplexarier requiere cotejo léxico adicional.'};
notes['250'] = {number:250,type:'SINTAXIS Y HUMOR',heading:'Gerundivos de castigo',text:'elinguandam dedero y castrandum loces emplean gerundivos acusativos que expresan la finalidad de entregar a alguien para recibir un castigo. El juramento de Euclión es una hipérbole dirigida a Estáfila, no una orden efectiva. Cotejo: Plauto, Aulularia 250–251, Friedrich Leo, Plauti Comoediae I (1895), Perseus Digital Library, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; análisis de la construcción en Rosemarie Lühr, Konkurrenzsyntax I, §2.6.7, https://dwee.saw-leipzig.de/Rosemarie_Luehr/userfiles/downloads/Projekte/PlautusAulularia.pdf.'};
notes['251'] = {number:251,type:'CRÍTICA TEXTUAL',heading:'Un ego suplementado',text:'En la transcripción de The Latin Library el pronombre ego aparece entre corchetes angulares, como suplemento editorial. Se presenta aquí sin marcas en la línea de lectura, pero no se atribuye sin reserva a la transmisión. Comparar https://www.thelatinlibrary.com/plautus/aulularia.shtml, Aulularia 251. Cotejo del aparato impreso de Leo pendiente.'};
notes['244–245'] = {number:244,type:'LÉXICO Y DRAMATURGIA',heading:'El desaire interpretado',text:'Megadoro interpreta la huida de Euclión como un rechazo social. certiorem facere significa informar o poner al corriente; fastidit mei construye el verbo de desdén con genitivo personal. Plauto, Aulularia 244–246; Friedrich Leo, Plauti comoediae (1895), edición digital Perseus, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['247'] = {number:247,type:'MORFOLOGÍA',heading:'Supino de finalidad',text:'petitum es supino en -um de peto, dependiente del verbo de movimiento it: «va a buscar». La secuencia pauperioris gratiam expresa el favor del más pobre; no debe confundirse el supino con un participio. Plauto, Aulularia 247–249; Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};


notes['328'] = {number:328,type:'CRÍTICA TEXTUAL',heading:'Texto suplementado y numeración 328a',text:'El texto de «cape atque abi intro ad nos» y «quem illic reliquit agnum» se transmite en la edición digital consultada entre corchetes angulares: es suplemento editorial, no debe considerarse testimonio íntegro. El número 328a distingue una línea intercalada en la numeración del pasaje. El comienzo de 329 contiene una laguna marcada por asteriscos, que aquí no se reconstruye. Cotejo: Plauto, Aulularia II.5, 327–330, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Aparato de Leo (1895) pendiente de comprobación directa.'};
notes['330'] = {number:330,type:'LÉXICO',heading:'Iniuria',text:'Iniuria puede funcionar adverbialmente, «injustamente», a partir del ablativo de iniuria; Congrión protesta por el reparto desigual de los corderos. Plauto, Aulularia II.5, 330–331, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};

notes['336'] = {number:336,type:'LÉXICO Y COMICIDAD',heading:'Hasta quedarse ronco',text:'Usque ad ravim describe una insistencia que desemboca en la ronquera; la repetición de poscam intensifica la queja del cocinero. Texto: Plauto, Aulularia II.5, 336–337, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Aparato crítico de Leo pendiente.'};
notes['341'] = {number:341,type:'MORFOLOGÍA',heading:'Adferto y la orden práctica',text:'Adferto es imperativo futuro de adfero en -to, frecuente en órdenes y prescripciones; abs te conserva la variante preposicional abs. La advertencia vuelve absurda la tarea del cocinero: deberá llevar desde su propia casa lo que necesite. Plauto, Aulularia II.5, 339–341; texto cotejado https://www.thelatinlibrary.com/plautus/aulularia.shtml; Leo, Plauti comoediae I (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'};

let lastNumber = '';
for (const entry of verses) {
  if (entry.n) lastNumber = entry.n;
  const row = document.createElement('div');
  row.className = 'verse';
  row.id = entry.stableId || ('v' + (entry.n || lastNumber + '-continuation'));
  const left = document.createElement('div');
  left.className = 'latin-side';
  const num = document.createElement('span');
  num.className = 'number';
  num.textContent = entry.n;
  const speech = document.createElement('div');
  speech.className = 'speech';
  if (entry.speaker) {
    const who = document.createElement('span');
    who.className = 'speaker';
    who.textContent = entry.speaker;
    speech.append(who);
  }
  const latin = document.createElement('p');
  latin.className = 'latin';
  const reference = (Number(lastNumber) <= 39 ? 'Prólogo' : Number(lastNumber) <= 78 ? 'I.1' : Number(lastNumber) <= 119 ? 'I.2' : Number(lastNumber) <= 177 ? 'II.1' : 'II.2') + ', v. ' + lastNumber;
  const chunks = entry.latin.match(/\p{L}+|[^\p{L}]+/gu) || [];
  let index = 0;
  for (const chunk of chunks) {
    if (!/^\p{L}/u.test(chunk)) {
      latin.append(document.createTextNode(chunk));
      continue;
    }
    const word = entry.words[index++];
    if (!word || word[0].toLocaleLowerCase('la') !== chunk.toLocaleLowerCase('la')) {
      throw new Error('Falta análisis o hay un desajuste en ' + entry.n + ': ' + chunk);
    }
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'token';
    button.textContent = chunk;
    button.setAttribute('aria-label', chunk + ': ver análisis morfológico');
    button.setAttribute('aria-pressed','false');
    button.addEventListener('click', () => openWord(button, word, reference));
    latin.append(button);
  }
  if (index !== entry.words.length) throw new Error('Sobran análisis en el verso ' + entry.n);
  const note = notes[entry.n];
  if (note) {
    latin.append(document.createTextNode(' '));
    const noteButton = document.createElement('button');
    noteButton.type = 'button';
    noteButton.className = 'note-anchor';
    noteButton.textContent = String(note.number);
    noteButton.setAttribute('aria-label', 'Nota ' + note.number + ': ' + note.heading);
    noteButton.setAttribute('aria-expanded','false');
    noteButton.addEventListener('click', () => openNote(noteButton, note));
    latin.append(noteButton);
  }
  speech.append(latin);
  left.append(num,speech);
  const right = document.createElement('p');
  right.className = 'spanish';
  right.textContent = entry.spanish;
  row.append(left,right);
  row.dataset.section = entry.section || (Number(lastNumber) <= 39 ? 'prologue' : Number(lastNumber) <= 78 ? 'act1scene1' : Number(lastNumber) <= 119 ? 'act1scene2' : Number(lastNumber) <= 177 ? 'act2scene1' : 'act2scene2');
  container.append(row);
}

saveWordButton.addEventListener('click', () => {
  if (!currentWord) return;
  const id = wordId(currentWord.word);
  const before = savedWords.slice();
  const index = savedWords.findIndex(item => item.id === id);
  if (index >= 0) savedWords.splice(index, 1);
  else savedWords.push({
    id, language: 'latín', form: currentWord.word[0], lemma: currentWord.word[1],
    morphology: currentWord.word[2], work: 'Plauto · Aulularia',
    reference: currentWord.reference, addedAt: new Date().toISOString()
  });
  if (!persistDictionary()) {
    savedWords = before;
    saveWordButton.textContent = 'No se pudo guardar en este navegador';
    return;
  }
  updateSaveButton();
  renderDictionary();
});

function renderDictionary() {
  document.querySelector('#saved-count').textContent = String(savedWords.length);
  document.querySelectorAll('.mobile-saved-count').forEach(node => node.textContent = savedWords.length ? '(' + savedWords.length + ')' : '');
  document.querySelector('#start-review').disabled = !savedWords.length;
  document.querySelector('#export-dictionary').disabled = !savedWords.length;
  const list = document.querySelector('#dictionary-list');
  list.replaceChildren();
  if (!savedWords.length) {
    const empty = document.createElement('p');
    empty.className = 'dictionary-empty';
    empty.textContent = 'Todavía no hay palabras guardadas. Seleccioná una palabra del latín y elegí «Guardar».';
    list.append(empty);
    return;
  }
  for (const item of savedWords) {
    const article = document.createElement('article');
    article.className = 'dictionary-entry';
    const content = document.createElement('div');
    const form = document.createElement('strong');
    form.textContent = item.form;
    const lemma = document.createElement('span');
    lemma.textContent = item.lemma + ' · ' + item.reference;
    content.append(form,lemma);
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', 'Quitar ' + item.form + ' del diccionario');
    remove.addEventListener('click', () => {
      const before = savedWords.slice();
      savedWords = savedWords.filter(word => word.id !== item.id);
      if (!persistDictionary()) { savedWords = before; return; }
      renderDictionary();
      updateSaveButton();
    });
    article.append(content,remove);
    list.append(article);
  }
}

function closeDrawer() {
  activeDrawer = null;
  drawer.hidden = true;
  sidebar.classList.remove('open');
  characterRail.classList.remove('open');
  tabs.filter(tab => tab.dataset.drawer === 'dictionary').forEach(tab => tab.setAttribute('aria-expanded','false'));
  document.querySelector('#flashcard').hidden = true;
  document.querySelector('#dictionary-list').hidden = false;
  syncPanelButtons();
}
function syncPanelButtons() {
  const compact = window.matchMedia('(max-width: 1160px)').matches;
  const mobile = window.matchMedia('(max-width: 860px)').matches;
  tabs.forEach(tab => {
    const type = tab.dataset.drawer;
    let expanded = type === 'dictionary' ? activeDrawer === 'dictionary' :
      type === 'position' ? (mobile ? sidebar.classList.contains('open') : !appShell.classList.contains('nav-collapsed')) :
      (compact ? characterRail.classList.contains('open') : !appShell.classList.contains('characters-collapsed'));
    tab.setAttribute('aria-expanded', String(expanded));
  });
}
function openDrawer(name) {
  closeWord();
  closeNote();
  const compact = window.matchMedia('(max-width: 1160px)').matches;
  const mobile = window.matchMedia('(max-width: 860px)').matches;
  if (name === 'position') {
    const wasOpen = mobile ? sidebar.classList.contains('open') : !appShell.classList.contains('nav-collapsed');
    closeDrawer();
    if (mobile) sidebar.classList.toggle('open', !wasOpen);
    else appShell.classList.toggle('nav-collapsed', wasOpen);
    syncPanelButtons();
    return;
  }
  if (name === 'characters') {
    const wasOpen = compact ? characterRail.classList.contains('open') : !appShell.classList.contains('characters-collapsed');
    closeDrawer();
    if (compact) characterRail.classList.toggle('open', !wasOpen);
    else appShell.classList.toggle('characters-collapsed', wasOpen);
    syncPanelButtons();
    return;
  }
  const wasOpen = activeDrawer === 'dictionary';
  closeDrawer();
  if (!wasOpen && name === 'dictionary') {
    activeDrawer = name;
    drawer.hidden = false;
    renderDictionary();
  }
  syncPanelButtons();
}
tabs.forEach(tab => tab.addEventListener('click', () => openDrawer(tab.dataset.drawer)));
document.querySelector('#close-drawer').addEventListener('click', closeDrawer);
document.querySelector('#return-to-text').addEventListener('click', closeDrawer);
document.querySelector('#close-word').addEventListener('click', closeWord);
document.querySelector('#close-note').addEventListener('click', closeNote);

document.querySelector('#export-dictionary').addEventListener('click', () => {
  if (!savedWords.length) return;
  const blob = new Blob([JSON.stringify({version:1, words:savedWords},null,2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'edicion-viva-diccionario.json';
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});
document.querySelector('#import-trigger').addEventListener('click', () => document.querySelector('#import-dictionary').click());
document.querySelector('#import-dictionary').addEventListener('change', async event => {
  const file = event.target.files?.[0];
  if (!file) return;
  const feedback = document.querySelector('#dictionary-feedback');
  try {
    const data = JSON.parse(await file.text());
    if (data.version !== 1 || !Array.isArray(data.words)) throw new Error('Formato no reconocido');
    const incoming = data.words.filter(item => item && typeof item.id === 'string' &&
      typeof item.form === 'string' && typeof item.lemma === 'string' && typeof item.morphology === 'string');
    const before = savedWords.slice();
    const known = new Set(savedWords.map(item => item.id));
    let count = 0;
    for (const item of incoming) {
      if (!known.has(item.id)) { savedWords.push(item); known.add(item.id); count++; }
    }
    if (!persistDictionary()) { savedWords = before; throw new Error('No se pudo guardar'); }
    feedback.textContent = count + ' palabra(s) importada(s).';
    renderDictionary();
  } catch {
    feedback.textContent = 'No se pudo importar ese archivo JSON.';
  }
  event.target.value = '';
});

function showCard() {
  const card = reviewDeck[reviewIndex];
  document.querySelector('#flash-progress').textContent = (reviewIndex + 1) + ' de ' + reviewDeck.length;
  document.querySelector('#flash-form').textContent = card.form;
  document.querySelector('#flash-lemma').textContent = card.lemma;
  document.querySelector('#flash-morph').textContent = card.morphology;
  document.querySelector('#flash-answer').hidden = true;
  document.querySelector('#reveal-card').hidden = false;
  document.querySelector('#next-card').hidden = true;
}

document.querySelector('#start-review').addEventListener('click', () => {
  reviewDeck = savedWords.slice();
  if (!reviewDeck.length) return;
  reviewIndex = 0;
  document.querySelector('#dictionary-list').hidden = true;
  document.querySelector('#flashcard').hidden = false;
  showCard();
});
document.querySelector('#reveal-card').addEventListener('click', () => {
  document.querySelector('#flash-answer').hidden = false;
  document.querySelector('#reveal-card').hidden = true;
  document.querySelector('#next-card').hidden = false;
});
document.querySelector('#next-card').addEventListener('click', () => {
  reviewIndex = (reviewIndex + 1) % reviewDeck.length;
  showCard();
});
document.querySelector('#end-review').addEventListener('click', () => {
  document.querySelector('#flashcard').hidden = true;
  document.querySelector('#dictionary-list').hidden = false;
  renderDictionary();
});

function trackAnchor() {
  for (const [anchor, popover] of [[selected,wordPanel],[noteAnchor,notePanel]]) {
    if (!anchor || popover.hidden) continue;
    const r = anchor.getBoundingClientRect();
    if (r.bottom < 0 || r.top > window.innerHeight) {
      popover === wordPanel ? closeWord() : closeNote();
    } else positionPopover(anchor,popover);
  }
}
window.addEventListener('scroll', trackAnchor, {passive:true});
window.addEventListener('resize', trackAnchor);
document.addEventListener('pointerdown', event => {
  if (!wordPanel.hidden && !wordPanel.contains(event.target) && !event.target.closest('.token')) closeWord();
  if (!notePanel.hidden && !notePanel.contains(event.target) && !event.target.closest('.note-anchor')) closeNote();
  if (!drawer.hidden && !drawer.contains(event.target) && !event.target.closest('.side-tabs')) closeDrawer();
});
document.addEventListener('keydown', event => {
  if (event.key === 'Escape') {
    closeWord();
    closeNote();
    closeDrawer();
  }
});
renderDictionary();
syncPanelButtons();
window.addEventListener('edicion-viva:dictionary-updated', event => {
  if (event.detail?.language !== 'la') return;
  savedWords = readDictionary();
  renderDictionary();
  updateSaveButton();
});
window.addEventListener('resize', syncPanelButtons);

/* Navegación editorial: se deriva de las secciones realmente publicadas.
   Los futuros bloques pueden declarar entry.section y se incorporan sin editar el menú. */
const sectionSelector = document.createElement('select');
sectionSelector.id = 'section-selector';
sectionSelector.setAttribute('aria-label','Elegir sección de la obra');
const sectionNames = {
  prologue:'Prólogo · Lar familiar',
  act1scene1:'Acto I, escena 1',
  act1scene2:'Acto I, escena 2',
  act2scene1:'Acto II, escena 1',
  act2scene2:'Acto II, escena 2',
  act2scene3:'Acto II, escena 3',
  act2scene4:'Acto II, escena 4',
  act2scene5:'Acto II, escena 5',
  act2scene6:'Acto II, escena 6',
  act2scene7:'Acto II, escena 7',
  act2scene8:'Acto II, escena 8',
  act2scene9:'Acto II, escena 9',
  act3scene1:'Acto III, escena 1'
};
const sectionRanges = new Map();
for (const row of container.querySelectorAll('.verse[data-section]')) {
  const section = row.dataset.section;
  const raw = row.querySelector('.verse-number')?.textContent || row.querySelector('.number')?.textContent || '';
  const numbers = (raw.match(/\d+/g) || []).map(Number);
  if (!sectionRanges.has(section)) sectionRanges.set(section, []);
  sectionRanges.get(section).push(...numbers);
}
for (const [section,numbers] of sectionRanges) {
  const name = sectionNames[section] || section.replace(/^act(\d+)scene(\d+)$/, 'Acto $1, escena $2');
  const min = numbers.length ? Math.min(...numbers) : '';
  const max = numbers.length ? Math.max(...numbers) : '';
  const option = document.createElement('option');
  option.value = section;
  option.textContent = name + (numbers.length ? ' · vv. ' + min + '–' + max : '');
  sectionSelector.append(option);
}
const sectionNav=document.createElement('nav');
sectionNav.className='section-navigation';
sectionNav.append(sectionSelector);
document.querySelector('#section-nav-slot').append(sectionNav);
function selectSection(section) {
  for (const row of container.querySelectorAll('.verse')) row.hidden = row.dataset.section !== section;
  const name = sectionNames[section] || section.replace(/^act(\d+)scene(\d+)$/, 'Acto $1, escena $2');
  const current=document.querySelector('.position-current');
  if (current) current.textContent=name;
  const numbers=sectionRanges.get(section)||[];
  const marker=document.querySelector('.position-marker strong');
  if (marker && numbers.length) marker.textContent='vv. '+Math.min(...numbers)+'–'+Math.max(...numbers);
  closeWord(); closeNote();
}
sectionSelector.addEventListener('change',()=>selectSection(sectionSelector.value));
if (sectionSelector.options.length) selectSection(sectionSelector.value);
